import type {
  AnyCircuitElement,
  PcbCourtyardRect,
  PcbSilkscreenPath,
} from "circuit-json"
import { type SilkscreenRef, silkscreenRef } from "src/helpers/silkscreenRef"
import { z } from "zod"
import { rectpad } from "../helpers/rectpad"
import { base_def } from "../helpers/zod/base_def"

export const sot23w_def = base_def.extend({
  fn: z.string(),
  num_pins: z.number().default(3),
  w: z.string().default("3.40mm"),
  h: z.string().default("3.30mm"),
  pl: z.string().default("1mm"),
  pw: z.string().default("0.7mm"),
  p: z.string().default("1.2mm"),
  string: z.string().optional(),
})

export const sot23w = (
  raw_params: z.input<typeof sot23w_def>,
): { circuitJson: AnyCircuitElement[]; parameters: any } => {
  const match = raw_params.string?.match(/^sot23w_(\d+)/)
  const numPins = match ? Number.parseInt(match[1]!, 3) : 3

  const parameters = sot23w_def.parse({
    ...raw_params,
    num_pins: numPins,
  })

  if (parameters.num_pins === 3) {
    return {
      circuitJson: sot23w_3(parameters),
      parameters: parameters,
    }
  }

  throw new Error("Invalid number of pins")
}

export const getCcwSot23wCoords = (parameters: {
  num_pins: number
  pn: number
  w: number
  h: number
  pl: number
  p: number
}) => {
  const { pn, w, h, pl, p } = parameters

  if (pn === 1) {
    return { x: -p, y: 0.95 }
  }
  if (pn === 2) {
    return { x: -p, y: -0.95 }
  }

  return { x: p, y: 0 }
}

export const sot23w_3 = (parameters: z.infer<typeof sot23w_def>) => {
  const pads: AnyCircuitElement[] = []
  const w = Number.parseFloat(parameters.w)
  const h = Number.parseFloat(parameters.h)
  const pl = Number.parseFloat(parameters.pl)
  const pw = Number.parseFloat(parameters.pw)
  const p = Number.parseFloat(parameters.p)
  const cornerRadius = Math.min(pl, pw) / 8

  for (let i = 0; i < parameters.num_pins; i++) {
    const { x, y } = getCcwSot23wCoords({
      num_pins: parameters.num_pins,
      pn: i + 1,
      w,
      h,
      pl,
      p,
    })
    pads.push(rectpad(i + 1, x, y, pl, pw, cornerRadius))
  }

  const silkscreenRefText: SilkscreenRef = silkscreenRef(
    0,
    Number.parseInt(parameters.h) / 2 + 1,
    0.3,
  )

  const width = w / 2 - 1
  const height = h / 2
  const silkscreenPath1: PcbSilkscreenPath = {
    layer: "top",
    pcb_component_id: "",
    pcb_silkscreen_path_id: "silkscreen_path_1",
    route: [
      { x: -width, y: height },
      { x: width + 0.3, y: height },
      { x: width + 0.3, y: height / 2 },
    ],
    type: "pcb_silkscreen_path",
    stroke_width: 0.1,
  }
  const silkscreenPath2: PcbSilkscreenPath = {
    layer: "top",
    pcb_component_id: "",
    pcb_silkscreen_path_id: "silkscreen_path_2",
    route: [
      { x: -width, y: -height },
      { x: width + 0.3, y: -height },
      { x: width + 0.3, y: -height / 2 },
    ],
    type: "pcb_silkscreen_path",
    stroke_width: 0.1,
  }

  const padToeHalfWidth = p + pl / 2
  const pinRowHalfHeight = 0.95 + pw / 2
  const bodyHalfHeight = h / 2
  const courtyardHalfWidth = padToeHalfWidth + 0.25
  const courtyardHalfHeight = Math.max(
    pinRowHalfHeight + 0.25,
    bodyHalfHeight + 0.09,
  )
  const courtyard: PcbCourtyardRect = {
    type: "pcb_courtyard_rect",
    pcb_courtyard_rect_id: "",
    pcb_component_id: "",
    center: { x: 0, y: 0 },
    width: 2 * courtyardHalfWidth,
    height: 2 * courtyardHalfHeight,
    layer: "top",
  }

  return [
    ...pads,
    silkscreenPath1,
    silkscreenPath2,
    silkscreenRefText as AnyCircuitElement,
    courtyard,
  ]
}
