import type {
  AnyCircuitElement,
  PcbCourtyardOutline,
  PcbSilkscreenPath,
} from "circuit-json"
import { length } from "circuit-json"
import { z } from "zod"
import { rectpad } from "../helpers/rectpad"
import { silkscreenRef, type SilkscreenRef } from "../helpers/silkscreenRef"
import { base_def } from "../helpers/zod/base_def"
import { u_curve } from "../helpers/u-curve"
import { createRectUnionOutline } from "src/helpers/rect-union-outline"
import { dim2d } from "src/helpers/zod/dim-2d"
import {
  createThermalPad,
  thermalPadOffsetFields,
} from "src/helpers/create-thermal-pad"

// TODO we should accept MS-012 or MS-013

export const ssop_def = base_def
  .extend({
    fn: z.string(),
    bodywidth: length
      .refine((value) => Number.isFinite(value) && value > 0, {
        message: "bodywidth must be a positive finite length",
      })
      .optional()
      .describe(
        "physical body X size before footprint rotation, independent of copper",
      ),
    bodyheight: length
      .refine((value) => Number.isFinite(value) && value > 0, {
        message: "bodyheight must be a positive finite length",
      })
      .optional()
      .describe(
        "physical body Y size before footprint rotation, independent of copper",
      ),
    bodythickness: length
      .refine((value) => Number.isFinite(value) && value > 0, {
        message: "bodythickness must be a positive finite length",
      })
      .optional()
      .describe(
        "physical body Z size, excluding board standoff; metadata for 3D consumers",
      ),
    num_pins: z.number().optional().default(8),
    w: length.default(length.parse("3.9mm")),
    p: length.default(length.parse("1.27mm")),
    pw: length.optional(),
    pl: length.optional(),
    legsoutside: z.boolean().optional().default(false),
    thermalpad: dim2d.optional(),
    ...thermalPadOffsetFields,
    silkscreen_stroke_width: z.number().optional().default(0.1),
  })
  .transform((v) => {
    if (v.pw == null && v.pl == null) {
      v.pw = length.parse("0.51mm")
      v.pl = length.parse("1.1mm")
    } else if (v.pw == null) {
      v.pw = v.pl! * (0.51 / 1.1)
    } else if (v.pl == null) {
      v.pl = v.pw! * (1.1 / 0.51)
    }

    return v as {
      bodywidth?: number
      bodyheight?: number
      bodythickness?: number
      w: number
      p: number
      pw: number
      pl: number
      num_pins: number
      legsoutside: boolean
      thermalpad?: { x: number; y: number }
      thermalpadcenteroffsetx: number
      thermalpadcenteroffsety: number
      silkscreen_stroke_width?: number
      fn: string
    }
  })

export type SsopInput = z.infer<typeof ssop_def>

const getSsopCoords = (parameters: {
  num_pins: number
  pn: number
  w: number
  p: number
  pl: number
  legsoutside: boolean
}) => {
  const { num_pins, pn, w, p } = parameters
  const ph = num_pins / 2
  const isLeft = pn <= ph
  const leftPinGaps = ph - 1
  const gs = p
  const h = gs * leftPinGaps
  const padRowSpan = w + length.parse("0.2mm")
  const x = (isLeft ? -1 : 1) * (padRowSpan / 2)

  if (isLeft) {
    return { x, y: h / 2 - (pn - 1) * gs }
  }
  return { x, y: -h / 2 + (pn - ph - 1) * gs }
}

export const ssop = (
  raw_params: SsopInput,
): { circuitJson: AnyCircuitElement[]; parameters: SsopInput } => {
  const parameters = ssop_def.parse(raw_params)
  const pads: AnyCircuitElement[] = []
  const cornerRadius = Math.min(parameters.pl, parameters.pw) / 8

  for (let i = 0; i < parameters.num_pins; i++) {
    const { x, y } = getSsopCoords({
      num_pins: parameters.num_pins,
      pn: i + 1,
      w: parameters.w,
      p: parameters.p,
      pl: parameters.pl,
      legsoutside: parameters.legsoutside,
    })
    pads.push(rectpad(i + 1, x, y, parameters.pl, parameters.pw, cornerRadius))
  }

  if (parameters.thermalpad) {
    pads.push(
      createThermalPad(parameters.thermalpad, {
        x: parameters.thermalpadcenteroffsetx,
        y: parameters.thermalpadcenteroffsety,
      }),
    )
  }

  const m = Math.min(1, parameters.p / 2)
  const sw = parameters.w - (parameters.legsoutside ? 0 : parameters.pl) - 0.2
  const sh = (parameters.num_pins / 2 - 1) * parameters.p + parameters.pw + m
  const silkscreenRefText: SilkscreenRef = silkscreenRef(
    0,
    sh / 2 + 0.4,
    sh / 12,
  )
  const silkscreenBorder: PcbSilkscreenPath = {
    type: "pcb_silkscreen_path",
    layer: "top",
    pcb_component_id: "",
    pcb_silkscreen_path_id: "silkscreen_path_1",
    stroke_width: parameters.silkscreen_stroke_width ?? 0.1,
    route: [
      { x: -sw / 2, y: -sh / 2 },
      { x: -sw / 2, y: sh / 2 },
      ...u_curve.map(({ x, y }) => ({
        x: (x * sw) / 6,
        y: (y * sw) / 6 + sh / 2,
      })),
      { x: sw / 2, y: sh / 2 },
      { x: sw / 2, y: -sh / 2 },
      { x: -sw / 2, y: -sh / 2 },
    ],
  }

  const pinRowSpanY =
    (parameters.num_pins / 2 - 1) * parameters.p + parameters.pw
  const padToeHalfX = parameters.legsoutside
    ? parameters.w / 2 + parameters.pl
    : (parameters.w + 0.2) / 2 + parameters.pl / 2
  const pinRowHalfY = pinRowSpanY / 2
  const courtyardStepOuterHalfWidth = padToeHalfX + 0.25
  const courtyardStepInnerHalfWidth = courtyardStepOuterHalfWidth
  const courtyardStepOuterHalfHeight = pinRowHalfY + 0.445
  const courtyardStepInnerHalfHeight = courtyardStepOuterHalfHeight
  const courtyard: PcbCourtyardOutline = {
    type: "pcb_courtyard_outline",
    pcb_courtyard_outline_id: "",
    pcb_component_id: "",
    outline: createRectUnionOutline([
      {
        minX: -courtyardStepOuterHalfWidth,
        maxX: courtyardStepOuterHalfWidth,
        minY: -courtyardStepInnerHalfHeight,
        maxY: courtyardStepInnerHalfHeight,
      },
      {
        minX: -courtyardStepInnerHalfWidth,
        maxX: courtyardStepInnerHalfWidth,
        minY: -courtyardStepOuterHalfHeight,
        maxY: courtyardStepOuterHalfHeight,
      },
    ]),
    layer: "top",
  }

  if (
    parameters.bodywidth !== undefined ||
    parameters.bodyheight !== undefined
  ) {
    // Keep the original courtyard when no body outline is supplied. With an
    // explicit outline, enclose both the physical body and every copper pad,
    // including an offset thermal pad. An omitted axis retains legacy bounds.
    let halfWidth =
      parameters.bodywidth === undefined
        ? courtyardStepOuterHalfWidth
        : parameters.bodywidth / 2 + 0.25
    let halfHeight =
      parameters.bodyheight === undefined
        ? courtyardStepOuterHalfHeight
        : parameters.bodyheight / 2 + 0.25
    for (const pad of pads) {
      if (pad.type !== "pcb_smtpad" || pad.shape !== "rect") continue
      halfWidth = Math.max(halfWidth, Math.abs(pad.x) + pad.width / 2 + 0.25)
      halfHeight = Math.max(halfHeight, Math.abs(pad.y) + pad.height / 2 + 0.25)
    }
    courtyard.outline = [
      { x: -halfWidth, y: -halfHeight },
      { x: halfWidth, y: -halfHeight },
      { x: halfWidth, y: halfHeight },
      { x: -halfWidth, y: halfHeight },
      { x: -halfWidth, y: -halfHeight },
    ]
  }

  return {
    circuitJson: [...pads, silkscreenBorder, silkscreenRefText, courtyard],
    parameters,
  }
}
